def transform(grid):
    h, w = len(grid), len(grid[0])
    row_clues = {}
    for r, row in enumerate(grid):
        if all(color != 0 and color == row[0] for color in row):
            row_clues[r] = row[0]
    if row_clues:
        period = len(row_clues)
        phases = {r % period: color for r, color in row_clues.items()}
        if len(phases) == period:
            return [[phases[r % period] for _ in range(w)] for r in range(h)]

    options = []
    for kind in ("difference", "sum"):
        lines = {}
        for r, row in enumerate(grid):
            for c, color in enumerate(row):
                if color:
                    offset = c - r if kind == "difference" else c + r
                    if offset in lines and lines[offset] != color:
                        break
                    lines[offset] = color
            else:
                continue
            break
        else:
            period = len(lines)
            phases = {offset % period: color for offset, color in lines.items()}
            if len(phases) == period:
                options.append((period, kind, phases))
    if not options:
        raise ValueError("No consistent diagonal stripe pattern")
    _, kind, phases = min(options, key=lambda item: item[0])
    if kind == "difference":
        return [[phases[(c - r) % len(phases)] for c in range(w)] for r in range(h)]
    return [[phases[(c + r) % len(phases)] for c in range(w)] for r in range(h)]
